// Builds blend-loft.json (ROUND 4: live truck, windows, post-check; copy of make-rows3 with an override section at the end) from blend-loft.r4-results.json (harness blend-loft.r3.mjs), blend-loft.r4-measure-results.json (round-1 raw) and blend-loft.r4-r1-guard.json.
//   bun contract/blend-loft.make-rows3.mjs
// Status of a row = what a student gets through the GUARDED rig (spike translator behind contract/blend-loft.guard.mjs). Each row's evidence leads with the RAW
// (unguarded translator) numbers, then the GUARD outcome. Nothing in packages/ or phase0/ was edited: the guard lives in contract/.
import { readFileSync, writeFileSync } from 'node:fs';
const C = '/home/shuff57/Documents/GitHub/reshape-cad/docs/spikes/solidcraft-referee/contract';
const J = JSON.parse(readFileSync(`${C}/blend-loft.r4-results.json`, 'utf8'));
const R1raw = JSON.parse(readFileSync(`${C}/blend-loft.r4-measure-results.json`, 'utf8'));
const G1 = JSON.parse(readFileSync(`${C}/blend-loft.r4-r1-guard.json`, 'utf8'));
const r1 = (id) => R1raw.find((r) => r.id === id);
const g1 = (id) => G1.rows.find((r) => r.id === id);
const f = (x) => (typeof x === 'number' ? x.toExponential(1) : String(x));
const v4 = (x) => (typeof x === 'number' ? x.toFixed(4) : String(x));
const v3 = (x) => (typeof x === 'number' ? x.toFixed(3) : String(x));
const ALL = J.ALL;
const bar = (c) => (c.kind === 'curved' ? 3e-4 : 1e-9);
const built = (c) => c.truck !== undefined && c.occt !== undefined;
const rawWrong = (c) => built(c) && !(c.dTO <= bar(c));
const sentenceOf = (code) => {
  const hit = [...ALL.filter((c) => c.guard?.code === code).map((c) => c.guard.sentence), ...J.N8.flatMap((e) => e.blends.filter((b) => b.guard === code).map((b) => b.sentence))][0];
  if (!hit) throw new Error('no sentence for guard code ' + code);
  return hit;
};
const codeStats = (code) => {
  const a = ALL.filter((c) => c.guard?.code === code);
  const wrong = a.filter(rawWrong).length; const noOracle = a.filter((c) => c.truck !== undefined && c.occt === undefined).length; const truckNone = a.filter((c) => c.truck === undefined).length; const exact = a.filter((c) => built(c) && !rawWrong(c)).length;
  const scripts = J.N8.filter((e) => e.blends.some((b) => b.guard === code)).length;
  const r1c = G1.rows.filter((r) => r.guard === code); const r1wrong = r1c.filter((r) => r.truckBuilt && !r.exact).length;
  const md = a.length ? `${a.length} ModelDoc cases in this harness (${wrong} RAW wrong vs OCCT, ${noOracle} built by truck while OCCT builds nothing, ${truckNone} where truck built nothing, ${exact} exact anyway) + ` : 'script-level only: ';
  return `${md}${scripts} N8 scripts + ${r1c.length} round-1 scripts (${r1wrong} RAW wrong, ${r1c.filter((r) => r.exact).length} exact anyway)`;
};
const sentenceOfLabel = (start) => { const c = ALL.find((x) => x.label.startsWith(start) && x.guard); if (!c) throw new Error('no guarded case ' + start); return c.guard.sentence; };
const CMD4 = 'LIVE round 4 (every truck number below was measured this session on the fe3717f pkg $S/sc-referee-pkg; none is replayed from an earlier pkg run): contract/blend-loft.r4.mjs (deterministic battery, planar fuzz, 50 script texts), contract/blend-loft.fuzz-live.mjs (random populations: bun ... --seed=<s> --n=<n> --modes=<m> --refused=0|1), contract/blend-loft.options-live.mjs, and the gate contract/blend-loft.guard-check.mjs that runs all three (exit 1 on any pass-but-wrong), each as SOLIDCRAFT_REFEREE_PKG=<pkg> systemd-run --user --scope -p MemoryMax=16G -p MemorySwapMax=0 bun <script> from the repo (no shadow root). Metric: TRUE relative volume error |truck-OCCT|/|OCCT| (rounds 1-3 divided by max(|OCCT|,1), which turned the 3e-4 curved bar into an absolute 3e-4 mm3 for any solid under 1 mm3). Bars: 1e-9 and equal face counts for straight-sided pairs; 3e-4 when a circle or an arc is involved (truck volumes are tessellation-derived).';
const CMD = CMD4;
const rows = [];
const row = (feature, status, evidence, refusalSentence) => rows.push({ feature, status, ...(refusalSentence ? { refusalSentence } : {}), evidence: `${CMD} ${evidence}` });
const lab = (arr, key) => arr.find((x) => x.label.startsWith(key));

// ---------------------------------------------------------------------------------------------------------------------
// aggregate guard statistics (the enforcement numbers)
// ---------------------------------------------------------------------------------------------------------------------
const polyCircle = ALL.filter((c) => c.kind === 'polygon' || c.kind === 'curved');
const passAll = polyCircle.filter((c) => !c.guard);
const passWrong = passAll.filter((c) => !(built(c) && c.dTO <= bar(c)));
const refAll = polyCircle.filter((c) => c.guard);
const refWouldBeWrong = refAll.filter(rawWrong);
const refNoSolid = refAll.filter((c) => !built(c));
const refExact = refAll.filter((c) => built(c) && c.dTO <= bar(c));
const N7 = J.N7, N7h = J.N7h, N7p2 = J.N7p2;
const n7pass = N7.filter((x) => !x.guard), n7hpass = N7h.filter((x) => !x.guard);
const N8 = J.N8; const n8pass = N8.flatMap((e) => e.blends.filter((b) => !b.guard));
const ENF = {
  gate: 'bun contract/blend-loft.guard-check.mjs',
  guard: 'contract/blend-loft.guard.mjs (rules), contract/blend-loft.guarded-run.mjs (script text: sketch offsets before blend() rewrote them), contract/blend-loft.r1-guard.mjs (round-1 replay)',
  supportedSet: 'S1 two straight-sided sketches, equal corner count, every side parallel (same direction) to its matching side, one unambiguous matching, and the kernel start-vertex rule lands on it; S2 circle<->circle; S3 regular 3/4/5/6/8-gon with a corner pointing along +u <-> circle; S4 axis-aligned rectangle (long side <= 2x short) <-> circle; S5 rounded rectangle (4 equal corners, long side <= 1.35x short) <-> circle; AND the sketches are on one named plane, gap >= 1e-6, drawn, not frame-placed, not shared with another feature after the loft moves them.',
  cases: { modelDocCases: polyCircle.length, guardPassed: passAll.length, guardPassedButWrong: passWrong.length, guardRefused: refAll.length, refusedThatWouldHaveBeenWrong: refWouldBeWrong.length, refusedWhereTruckBuiltNothing: refNoSolid.length, refusedButExactAnyway: refExact.length },
  fuzzPlanarSided: { seed4242: { pairs: N7.length, passed: n7pass.length, maxTruckVsClosedForm: Math.max(...n7pass.map((x) => x.dTG)), maxOcctVsClosedForm: Math.max(...n7pass.map((x) => x.dOG)) }, frontAndSidePlanesSeed31337: { pairs: N7p2.length, passed: N7p2.filter((x) => !x.guard).length, maxTruckVsClosedForm: Math.max(...N7p2.filter((x) => !x.guard).map((x) => x.dTG)), maxOcctVsClosedForm: Math.max(...N7p2.filter((x) => !x.guard).map((x) => x.dOG)) }, holdoutSeed99991: { pairs: N7h.length, passed: n7hpass.length, maxTruckVsClosedForm: Math.max(...n7hpass.map((x) => x.dTG)), maxOcctVsClosedForm: Math.max(...n7hpass.map((x) => x.dOG)) } },
  scriptBattery: { scripts: N8.length, blendsPassed: n8pass.length, passedButNotExact: J.N8wrongBuilt },
  round1Replay: G1.summary,
};
if (passWrong.length || J.N8wrongBuilt || ENF.fuzzPlanarSided.seed4242.maxTruckVsClosedForm > 1e-9 || ENF.fuzzPlanarSided.holdoutSeed99991.maxTruckVsClosedForm > 1e-9 || ENF.fuzzPlanarSided.frontAndSidePlanesSeed31337.maxTruckVsClosedForm > 1e-9) throw new Error('GUARD HAS A FALSE PASS: ' + JSON.stringify({ passWrong: passWrong.map((c) => c.label), n8: J.N8wrongBuilt }));
const enfTxt = `GUARD (not wired into the product; packages/script and phase0 are read-only here): ${ENF.cases.guardPassed} of ${ENF.cases.modelDocCases} straight/curved ModelDoc cases pass, ALL ${ENF.cases.guardPassed} exact vs OCCT (bar 1e-9 straight, 3e-4 curved); ${ENF.cases.guardRefused} refused of which ${ENF.cases.refusedThatWouldHaveBeenWrong} would have built a wrong solid, ${ENF.cases.refusedWhereTruckBuiltNothing} the kernel refused anyway, ${ENF.cases.refusedButExactAnyway} were exact (over-refusal, accepted).`;

// ---------------------------------------------------------------------------------------------------------------------
