const regOK = E10.filter((x) => /^reg n=\d ph=0\.000 /.test(x.label));
const n9pass = J.N9.filter((x) => !x.guard); const n9rect = n9pass.filter((x) => x.label.startsWith('rect 40x30')); const n9hex = n9pass.filter((x) => x.label.startsWith('hex phase0'));
row('blend: regular polygon (3, 4, 5, 6, 8 corners) with a corner pointing along +u from its centre <-> circle, polygon first or circle first', 'supported',
  `${regOK.map((x) => `${x.label.replace('reg ', '')} OCCT ${v3(x.occt)} truck ${v3(x.truck)} dVol ${f(x.d)}`).join('; ')}. Max ${f(Math.max(...regOK.map((x) => x.d)))} (n=3 circle->polygon), inside the curved bar 3e-4 by 1.5x; face counts equal. Off-centre hexagon vs circle at (5,3) and (15,-8): ${E10.filter((x) => x.label.startsWith('reg hex ph0 circle off-centre')).map((x) => f(x.d)).join(', ')}. Start corner and winding do not matter (N9): hexagon (corner on +u) listed from corners 0/2/4 counter-clockwise and 0/3 clockwise against d20, both directions: ${n9hex.length} cases, max ${f(Math.max(...n9hex.map((x) => x.d)))}; rectangle 40x30 from each of its 4 corners, CCW and CW, both directions: ${n9rect.length} cases, max ${f(Math.max(...n9rect.map((x) => x.d)))}; all guard-passed. Narrowed from round 2 to REGULAR polygons only (irregular ones are 4.9e-4..4.9e-3 off, next rows); n=7 and n>8 were not measured so they are refused, not guessed. Truck's volume ignores the polygon's rotation, OCCT's depends on it, hence the corner-on-+u condition. GUARD: passes exactly regular n in {3,4,5,6,8} with a corner within 1e-9 rad of +u.`);

const shapeOf = (x) => x.label.split(' d')[0]; const aspectOf = (k) => { const [w, h] = k.replace('rect ', '').split('x').map(Number); return Math.max(w, h) / Math.min(w, h); };
const shapes = [...new Set(J.XA.rc.map(shapeOf))];
const rcPass = J.XA.rc.filter((x) => aspectOf(shapeOf(x)) <= 2.0001); const rcOut = J.XA.rc.filter((x) => aspectOf(shapeOf(x)) > 2.0001);
const per = shapes.map((k) => { const a = J.XA.rc.filter((x) => shapeOf(x) === k); return `${k} (${aspectOf(k).toFixed(2)}:1) max ${f(Math.max(...a.map((x) => x.d)))}`; }).join(', ');
